INSERT INTO `ai_reports` VALUES (36,21,'2026-03-18','【昨日总结】：总热量约1450kcal，优质蛋白占比30%，但盐摄入可能偏高（全麦面包、鸡胸肉含隐形盐）  \n【病情关注】：加工主食和腌制品未记录钠含量，存在血压波动风险  \n【今日建议】：1.用无盐燕麦替换全麦面包  \n2.鸡胸肉改用柠檬汁+黑胡椒现场腌制  \n3.加餐选择低钠坚果（南瓜籽/腰果）替代包装食品  \n\n（注：建议严格称重鳕鱼和藜麦，海鱼类日摄入量控制在100g内以防钠超标）','2026-03-18 00:29:57'),(37,19,'2026-03-18','【昨日总结】：总热量约1400kcal，蛋白质占比30%（达标），碳水45%（略高），其中南瓜和藜麦可能影响血糖  \n\n【病情关注】：南瓜（高GI）和藜麦摄入可能引起血糖波动；燕麦片分量需明确（建议30g干重）  \n\n【今日建议】：  \n1. 用西葫芦替代南瓜作为蔬菜  \n2. 燕麦片减至30g干重，搭配10g奇亚籽延缓升糖  \n3. 晚餐苦瓜+豆腐组合保留，鸡胸肉增至120g提升饱腹感','2026-03-18 00:55:44'),(38,17,'2026-03-18','【昨日总结】：总热量约2100大卡，碳水50%、蛋白质30%合理，脂肪20%略低  \n【核心问题】：1. 优质脂肪摄入不足 2. 训练后补充窗口未体现  \n【今日建议】：1. 加餐坚果20g 2. 训练后补乳清蛋白+快碳 3. 烹调改用橄榄油','2026-03-18 01:34:18'),(39,18,'2026-03-18','【昨日总结】：总热量约1100kcal，蛋白质占35%偏高，碳水30%偏低，膳食纤维充足但全天总热量不足  \n【核心问题】：1.基础代谢未吃够 2.晚餐无主食导致碳水缺口  \n【今日建议】：  \n1.增加燕麦量至50g生重  \n2.晚餐加半根玉米  \n3.下午增补10颗巴旦木','2026-03-18 01:47:07'),(40,20,'2026-03-18','【昨日总结】：总热量1370kcal，结构合理。优质蛋白占比25%（达标），但饱和脂肪超限（来自三文鱼和鸡胸肉）。膳食纤维21g（达标）。\n\n【病情关注】：\n1. 三文鱼饱和脂肪含量较高\n2. 动物性脂肪来源偏多\n3. 全麦面包注意隐形添加脂肪\n\n【今日建议】：\n1. 三文鱼替换为鳕鱼或鲈鱼\n2. 增加豆制品替代部分肉类\n3. 全麦面包改用无糖无油款','2026-03-18 02:01:14'),(41,19,'2026-03-25','【昨日总结】：总热量约1600kcal，优质蛋白占比合理（28%），但精制碳水摄入偏高（藜麦+南瓜达45g）\n\n【病情关注】：\n1. 藜麦与南瓜同餐导致血糖负荷叠加（南瓜GI=75）\n2. 猕猴桃加餐时间距晚餐<2小时\n\n【今日建议】：\n1. 南瓜替换为西兰花（GI=15）\n2. 猕猴桃改至上午加餐\n3. 藜麦提前浸泡2小时降低升糖指数','2026-03-25 14:21:48'),(43,17,'2026-03-25','【昨日总结】：总热量约2200kcal，碳水50%偏高，蛋白质30%达标，脂肪20%略低\n\n【核心问题】：1. 增肌期脂肪摄入不足影响激素分泌 2. 训练后即时蛋白质补充不足\n\n【今日建议】：\n1. 晚餐牛肉替换为三文鱼（增加ω-3）\n2. 训练后30分钟内补充乳清蛋白粉\n3. 燕麦片添加10g坚果碎','2026-03-25 14:23:34');
