--
-- Table structure for table `foods`
--

DROP TABLE IF EXISTS `foods`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `foods` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `name` varchar(100) NOT NULL COMMENT '食物名称',
  `calories` double NOT NULL COMMENT '热量(kcal/100g)',
  `protein` double DEFAULT '0' COMMENT '蛋白质(g)',
  `fat` double DEFAULT '0' COMMENT '脂肪(g)',
  `carb` double DEFAULT '0' COMMENT '碳水(g)',
  `food_category` varchar(32) NOT NULL DEFAULT 'mixed' COMMENT 'staple/protein/vegetable/fruit/dairy/nut/mixed',
  `gi_level` varchar(16) DEFAULT 'medium' COMMENT 'low/medium/high',
  `sodium_mg` decimal(10,2) DEFAULT '0.00' COMMENT '每100g钠 mg',
  `saturated_fat` decimal(10,2) DEFAULT '0.00' COMMENT '每100g饱和脂肪 g',
  `fiber` decimal(10,2) DEFAULT '0.00' COMMENT '每100g膳食纤维 g',
  `sugar` decimal(10,2) DEFAULT '0.00' COMMENT '每100g糖 g',
  `breakfast_friendly` tinyint(1) NOT NULL DEFAULT '1' COMMENT '是否适合早餐',
  `dinner_friendly` tinyint(1) NOT NULL DEFAULT '1' COMMENT '是否适合晚餐',
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=101 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='食物营养表';
/*!40101 SET character_set_client = @saved_cs_client */;

